import pickle
import numpy as np

def analyze(filename):
    with open(filename, 'rb') as f:
        data = pickle.load(f)
        if isinstance(data, np.ndarray):
            return {
                'shape': data.shape,
                'type': str(data.dtype),
                'mean': float(data.mean())
            }
        else:
            return {
                'type': type(data).__name__,
                'description': str(data)[:100]  # First 100 characters if not numpy
            }

files = ["/home/ctfplayer/ctf_files/inputs/X.pkl", "/home/ctfplayer/ctf_files/inputs/X_test.pkl", "/home/ctfplayer/ctf_files/inputs/y.pkl"]
results = {}

for file in files:
    results[file] = analyze(file)

for file, result in results.items():
    print(f"Results for {file}:")
    for key, value in result.items():
        print(f"  {key}: {value}")
